    aboutTitle: "UniResto সম্পর্কে",
    aboutBody: "এটি লুক্সেমবার্গ বিশ্ববিদ্যালয়, ক্যাম্পাস কিরশবার্গের জন্য একটি প্রকল্প, যা বাস্তব, লাইভ Restopolis মেনু ডেটার উপর ভিত্তি করে তৈরি। কোনো অর্থ প্রদান করা হয় না এবং Restopolis-এর সাথে কোনো অর্ডার প্রদান বা ডেলিভারি করা হয় না — এখানে প্রতিটি অর্ডার শুধুমাত্র একটি অভ্যন্তরীণ রেকর্ড।",
