/** Translates a Restopolis category header if it's one of the 25 known,
 * verified strings above; otherwise returns it unchanged (never hides or
 * mistranslates a category this table doesn't know about yet). */
export function categoryLabel(rawCategory, lang) {
  const entry = CATEGORY_LABELS[rawCategory];
  return entry ? (entry[lang] || entry[DEFAULT_LANG] || rawCategory) : rawCategory;
}

// ---------------------------------------------------------------------------
// Dish name labels: UNLIKE categories/allergens, dish names are NOT a
// small closed set -- the DAILY menu (mains, starters, desserts, sides)
// rotates, so this table only covers the daily dishes on the menus when it
// was written; a dish that appears later is not in it and falls back to the
// raw (French) name, same "never hide, never guess" rule as
// categoryLabel(). (Translating new ones automatically as they show up would
// need a translation service -- see the git history for that discussion.)
//
// The FIXED products (every "01."-"12." Constant-products category:
// sandwiches, viennoiseries, dairy, ice cream, drinks, packaging) don't
// rotate, so all of them are covered: descriptive words are translated
// while a brand or coined name inside them stays as written ("Luxlait",
// "Rosport", "Great César", "ECOBOX", "Schockelasbotter"), the way an
// English menu abroad would keep them. A product that is ONLY a brand
// (Rosport Blue, Viva, Coca Cola, Lët'z kola, Ramborn ..., myMug ...,
// Nutchy) has no entry at all: there is nothing to translate, and the
// size that follows it is shown on its own line anyway (see dishTitle()).
// The 27 oldest entries were human-checked; the fixed-product and daily-dish
// entries were drafted by Claude in one pass and still want a native speaker's
// review, above all zh / hi / ar / bn / ur / lb. A well-known foreign
// culinary term (Béarnaise, mezze, falafel, croque monsieur, Orloff) is
// kept as-is inside a translation.
// ---------------------------------------------------------------------------

