/** Translates a dish/product name if it's one of the descriptive ones
 * covered in DISH_NAME_LABELS above; otherwise returns it unchanged --
 * covers only names actually seen so far (the menu rotates daily, this
 * can never be a closed set the way categories/allergens are) and
 * deliberately skips real product/brand names, which read as strange
 * translated (see the table's own comment). */
export function dishNameLabel(rawName, lang) {
  const entry = DISH_NAME_LABELS[rawName];
  return entry ? (entry[lang] || entry[DEFAULT_LANG] || rawName) : rawName;
}

// ---------------------------------------------------------------------------
// Sizes live in the card body, not in the item's name.
//
// Restopolis bakes the size/container into the dish name ("Rosport Blue 0,50
// l non consigné", "Mini salades 150 g", "Lait Luxlait BIO 0,25 l Tétra Pack
// (gratuit)", "Consigne ECOBOX (500 ml)", "Cornet Luxlait 130 ml (Chocolat,
// ...)"). The app shows the TITLE without it and the size on the card's own
// body line instead -- but it stays part of the raw name everywhere that
// names a real product (favorites keys, orders, emails, Telegram), since
// "Rosport Blue" alone doesn't say which of three bottles it is.
// ---------------------------------------------------------------------------

const _UNIT = "(?:kg|g|ml|cl|l)";
const _NUM = "\\d+(?:[.,]\\d+)?";
// A size as the French source writes it, in one of three shapes:
//   (500 ml)                                   -- parenthesised
//   150 g / 0,25 l btl / 0,50 l non consigné / 0,25 l Tétra Pack (gratuit)
//   0,33 btl                                   -- a bottle with no unit
const DISH_SIZE_RE = new RegExp(
  `\\s*(?:\\(\\s*(${_NUM}\\s*${_UNIT})\\s*\\)|(${_NUM}\\s*${_UNIT}\\b(?:\\s*(?:btl\\b|non[ -]consign\u00e9|T\u00e9tra Pack))?(?:\\s*\\(gratuit\\))?|${_NUM}\\s*btl\\b))`,
  "i"
);
// A translated name keeps its size at the END in the target language's own
// digits and unit word ("150克", "150 ग्राम", "١٥٠ غ", "১৫০ গ্রাম", "150 г").
const TRAILING_TRANSLATED_SIZE_RE = /\s*[\d\u0660-\u0669\u09E6-\u09EF][\d\u0660-\u0669\u09E6-\u09EF.,]*\s*[^\s\d]{1,12}$/u;

function _tidy(text) {
  return text.replace(/\s{2,}/g, " ").replace(/\s+([,)])/g, "$1").trim();
}

// The size as written in the source name ("0,25 l btl", "150 g",
// "500 ml"), or null when the name carries none.
export function dishSize(rawName) {
  const m = DISH_SIZE_RE.exec(rawName);
  return m ? (m[1] || m[2]).trim() : null;
}

// The name to show as an item's title: translated like dishNameLabel(), then
// with the size taken out. Names without a size come back untouched.
export function dishTitle(rawName, lang) {
  const label = dishNameLabel(rawName, lang);
  if (!DISH_SIZE_RE.test(rawName)) return label;
  // A translation that carries the size verbatim ("... 0,25 l Tétra Pack",
  // "... (500 ml)") loses exactly that text, whatever script surrounds it.
  const size = dishSize(rawName);
  if (label !== rawName && size && label.includes(size)) {
    const withoutSize = _tidy(label.replace(`(${size})`, "").replace(size, ""));
    if (withoutSize) return withoutSize;
  }
  const stripped = _tidy(label.replace(DISH_SIZE_RE, ""));
  if (stripped !== label) return stripped || label;
  // Translated names carry the size in the target language ("150 غ").
  const trailing = _tidy(label.replace(TRAILING_TRANSLATED_SIZE_RE, ""));
  return trailing || label;
}

// Title plus the size in brackets -- for plain one-line summaries (a
// courier's order list, order history) where there's no body line to put
// the size on but the exact product still matters.
export function dishTitleWithSize(rawName, lang) {
  const size = dishSize(rawName);
  return size ? `${dishTitle(rawName, lang)} (${size})` : dishTitle(rawName, lang);
}

// ---------------------------------------------------------------------------
// Allergen labels: the 14 EU 1169/2011 Annex II major allergens -- see
// restopolis/allergens.py's ALLERGEN_NAMES (the backend's French source
// of truth, by numeric code). This is the same standardized, legally
// defined 14-item list, not a guess at translating arbitrary text.
// ---------------------------------------------------------------------------

export const ALLERGEN_LABELS = {
  1: { en: "Gluten-containing cereals", zh: "含麸质谷物", hi: "लस युक्त अनाज", es: "Cereales que contienen gluten", fr: "Céréales contenant du gluten", ar: "حبوب تحتوي على الغلوتين", bn: "গ্লুটেনযুক্ত শস্য", pt: "Cereais que contêm glúten", ru: "Зерновые, содержащие глютен", ur: "گلوٹن والے اناج", lb: "Glutenhalteg Kären" },
  2: { en: "Crustaceans", zh: "甲壳类动物", hi: "क्रस्टेशियन (कवचयुक्त जीव)", es: "Crustáceos", fr: "Crustacés", ar: "القشريات", bn: "ক্রাস্টেসিয়ান", pt: "Crustáceos", ru: "Ракообразные", ur: "کرسٹیشین (خول دار آبی جاندار)", lb: "Kriibsdéieren" },
  3: { en: "Eggs", zh: "蛋类", hi: "अंडे", es: "Huevos", fr: "Œufs", ar: "بيض", bn: "ডিম", pt: "Ovos", ru: "Яйца", ur: "انڈے", lb: "Eeër" },
  4: { en: "Fish", zh: "鱼类", hi: "मछली", es: "Pescado", fr: "Poissons", ar: "أسماك", bn: "মাছ", pt: "Peixe", ru: "Рыба", ur: "مچھلی", lb: "Fësch" },
  5: { en: "Peanuts", zh: "花生", hi: "मूंगफली", es: "Cacahuetes", fr: "Arachides", ar: "الفول السوداني", bn: "চীনাবাদাম", pt: "Amendoim", ru: "Арахис", ur: "مونگ پھلی", lb: "Äerdnëss" },
  6: { en: "Soybeans", zh: "大豆", hi: "सोया", es: "Soja", fr: "Soja", ar: "فول الصويا", bn: "সয়াবিন", pt: "Soja", ru: "Соя", ur: "سویابین", lb: "Soja" },
  7: { en: "Milk", zh: "奶制品", hi: "दूध", es: "Leche", fr: "Lait", ar: "حليب", bn: "দুধ", pt: "Leite", ru: "Молоко", ur: "دودھ", lb: "Mëllech" },
  8: { en: "Tree nuts", zh: "坚果", hi: "मेवे (ट्री नट्स)", es: "Frutos de cáscara", fr: "Fruits à coque", ar: "المكسرات", bn: "বাদাম (ট্রি নাটস)", pt: "Frutos de casca rija", ru: "Орехи", ur: "درختی گری دار میوے", lb: "Nëss" },
  9: { en: "Celery", zh: "芹菜", hi: "अजवाइन (सेलेरी)", es: "Apio", fr: "Céleri", ar: "كرفس", bn: "সেলারি", pt: "Aipo", ru: "Сельдерей", ur: "اجوائن (سیلری)", lb: "Zelleri" },
  10: { en: "Mustard", zh: "芥末", hi: "सरसों", es: "Mostaza", fr: "Moutarde", ar: "خردل", bn: "সরিষা", pt: "Mostarda", ru: "Горчица", ur: "سرسوں", lb: "Moschtert" },
  11: { en: "Sesame seeds", zh: "芝麻", hi: "तिल", es: "Semillas de sésamo", fr: "Graines de sésame", ar: "بذور السمسم", bn: "তিল", pt: "Sementes de sésamo", ru: "Кунжут", ur: "تل کے بیج", lb: "Sesamkären" },
  12: { en: "Sulphur dioxide and sulphites", zh: "二氧化硫和亚硫酸盐", hi: "सल्फर डाइऑक्साइड और सल्फाइट्स", es: "Dióxido de azufre y sulfitos", fr: "Anhydride sulfureux et sulfites", ar: "ثاني أكسيد الكبريت والكبريتيت", bn: "সালফার ডাই অক্সাইড ও সালফাইট", pt: "Dióxido de enxofre e sulfitos", ru: "Диоксид серы и сульфиты", ur: "سلفر ڈائی آکسائیڈ اور سلفائٹس", lb: "Schwiefeldioxid a Sulfitter" },
  13: { en: "Lupin", zh: "羽扇豆", hi: "ल्यूपिन", es: "Altramuces", fr: "Lupin", ar: "الترمس", bn: "লুপিন", pt: "Tremoço", ru: "Люпин", ur: "لیوپن", lb: "Lupinnen" },
  14: { en: "Molluscs", zh: "软体动物", hi: "मोलस्क", es: "Moluscos", fr: "Mollusques", ar: "الرخويات", bn: "মলাস্ক", pt: "Moluscos", ru: "Моллюски", ur: "مولسکس (سیپ وغیرہ)", lb: "Mollusken" },
};

/** entry: {code, name, detail} from the API's allergens list. Translates
 * by numeric `code` against the standardized table above; falls back to
 * Restopolis's own (French) `name` if the code is missing/unmapped, then
 * to a bare "code N" -- same fallback chain as the backend already uses
 * (restopolis/allergens.py never drops an unknown code either). `detail`
 * (dish-specific free text, e.g. "Blé, Orge, Épeautre") is never
 * translated -- it's Restopolis's own arbitrary text, not a fixed term. */
export function allergenLabel(entry, lang) {
  const known = entry.code != null ? ALLERGEN_LABELS[entry.code] : null;
  if (known) return known[lang] || known[DEFAULT_LANG];
  return entry.name || `code ${entry.code}`;
}
